<script setup lang="ts">
import {ref,reactive} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import WorkspaceShell from '../../components/WorkspaceShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import {request,format,dateTime} from '../../api'
import {requireWorkspace,queryString,goCase,caseLabel,type Row} from '../../workspace'
const filter=reactive({date_from:'',date_to:'',account:'',business_type:'',reference:'',operation:'',result:''})
const items=ref<Row[]>([]),next=ref<number|null>(null),selected=ref<Row|null>(null),busy=ref(false),error=ref(''),queried=ref(false)
const kinds=[{id:'',name:'全部业务'},...Array.from({length:17},(_,i)=>{const id='UC'+String(i+1).padStart(2,'0');return{id,name:caseLabel(id,({UC02:'预约就诊',UC03:'变更预约',UC14:'预约与结算'} as Record<string,string>)[id]||id)}})]
const outcomes=[{id:'',name:'全部办理结果'},{id:'completed',name:'办理完成'},{id:'denied',name:'权限拒绝'}]
const names:Record<string,string>={save:'保存资料',book:'确认预约',cancel:'取消预约',reschedule:'改期接续',contact:'记录联系',arrive:'到店报到',start:'实际接诊',sign:'签署诊疗',draft:'保存草稿',exception:'记录待核实事实',correct:'办理更正',issue:'开具原就诊结算',replace:'替代出诊',publish:'发布出诊',stop:'登记停诊',approve:'批准',reject:'退回核实',source:'录入费用来源',review:'复核费用归属',submission:'报送齐备声明','review-submission':'复核齐备声明',confirm:'正式确认',analyze:'分析查询',phase:'阶段放行或暂停',calendar:'维护营业日历',operatory:'维护诊疗资源',grant:'授予岗位',revoke:'撤销授权',disable:'停用账号',enable:'启用账号',password:'重置口令'}
function operationLabel(value:string){return value.startsWith('denied.')?'拒绝：'+(names[value.slice(7)]||value.slice(7)):names[value]||value}
onShow(async()=>{if(await requireWorkspace('UC17'))await search()})
async function search(more=false){busy.value=true;error.value='';try{const data=await request('/api/audit?'+queryString({...filter,...(more&&next.value?{before:next.value}:{})}));items.value=more?[...items.value,...data.items]:data.items;next.value=data.next;selected.value=null;queried.value=true}catch(e:any){error.value=e.message}finally{busy.value=false}}
function changedSummary(value:string){try{const data=JSON.parse(value);return[data.fields?.join('、'),data.decision_reason?'核实原因：'+data.decision_reason:''].filter(Boolean).join('；')||'无字段变更'}catch{return value||'无字段变更'}}
function reset(){Object.assign(filter,{date_from:'',date_to:'',account:'',business_type:'',reference:'',operation:'',result:''});search()}
async function openSource(row:Row){error.value='';try{const result=await request('/api/audit/'+row.id+'/source');const {case:code,...params}=result.target;goCase(code,params)}catch(e:any){error.value=e.message}}
</script>
<template><WorkspaceShell title="业务操作记录" active="UC17" back><view class="page-heading"><view><text class="page-title">业务操作记录</text><text class="page-description">按实际账号、办理事项和发生时点追溯业务；原记录访问会再次核验权限。</text></view></view><view class="audit-filters surface"><view class="filter-grid"><view><text class="label">开始日期</text><picker mode="date" :value="filter.date_from" @change="filter.date_from=$event.detail.value"><view class="input">{{filter.date_from||'不限开始日期'}}</view></picker></view><view><text class="label">结束日期</text><picker mode="date" :value="filter.date_to" @change="filter.date_to=$event.detail.value"><view class="input">{{filter.date_to||'不限结束日期'}}</view></picker></view><view><text class="label">业务类型</text><picker :range="kinds" range-key="name" @change="filter.business_type=kinds[Number($event.detail.value)].id"><view class="input">{{kinds.find(k=>k.id===filter.business_type)?.name}}</view></picker></view><view><text class="label">账号或姓名</text><input class="input" v-model="filter.account" placeholder="输入账号或姓名" aria-label="账号或姓名"/></view><view><text class="label">原业务记录编号</text><input class="input" v-model="filter.reference" placeholder="精确匹配原记录编号" aria-label="原业务记录编号"/></view><view><text class="label">操作名称</text><input class="input" v-model="filter.operation" placeholder="如 cancel、sign、approve" aria-label="操作名称"/></view><view><text class="label">办理结果</text><picker :range="outcomes" range-key="name" @change="filter.result=outcomes[Number($event.detail.value)].id"><view class="input">{{outcomes.find(o=>o.id===filter.result)?.name}}</view></picker></view></view><view class="filter-actions"><text class="caption">按当前岗位和门店范围查询，不展示诊疗正文或口令。</text><button @click="reset" :disabled="busy">清除条件</button><button class="primary" @click="search()" :disabled="busy">{{busy?'查询中…':'查询记录'}}</button></view></view><view v-if="error" class="error">{{error}}</view><view class="audit-list"><button v-for="row in items" :key="row.id" class="audit-item" :class="{selected:selected?.id===row.id}" @click="selected=selected?.id===row.id?null:row"><view class="event-icon"><AppIcon :name="row.result==='denied'?'locked':'checkbox'" :size="22"/></view><view class="event-body"><view class="event-heading"><text>{{operationLabel(row.operation_name)}}</text><text class="event-time">{{dateTime(row.occurred_at)}}</text></view><text class="event-person">{{row.display_name||row.service_actor}} · {{row.role_name||'服务主体'}} · {{row.clinic_name||'集团范围'}}</text><text class="caption">{{caseLabel(row.object_kind,row.object_kind)}} · 原记录 {{row.business_reference}}</text></view><text class="status-label">{{row.result==='denied'?'权限拒绝':'办理完成'}}</text></button><view v-if="queried&&!items.length" class="empty-state"><AppIcon name="search" :size="32"/><text class="empty-title">没有匹配记录</text><text>可以调整期间或筛选条件；空结果不能解释为全系统从未发生操作。</text></view></view><button v-if="next" class="load-more" :disabled="busy" @click="search(true)">读取更早记录</button>
 <view v-if="selected" class="audit-detail surface"><view class="detail-bar"><text class="section-title">操作与版本引用</text><button class="icon-button" @click="selected=null" aria-label="关闭操作详情"><AppIcon name="closeempty"/></button></view><view class="version-comparison"><view><text class="caption">原版本</text><text>{{selected.previous_version_reference||'此旧记录没有保存原版本引用'}}</text></view><AppIcon name="right" :size="19"/><view><text class="caption">本次版本</text><text>{{selected.next_version_reference||'此操作没有新增版本引用'}}</text></view></view><view class="audit-meta"><view><text class="caption">办理字段</text><text>{{changedSummary(selected.changed_fields)}}</text></view><view><text class="caption">实际登录账号</text><text>{{selected.login_name||selected.service_actor}}</text></view><view><text class="caption">请求凭据</text><text>{{selected.request_id}}</text></view><view><text class="caption">结果摘要指纹</text><text>{{selected.result_digest}}</text></view></view><view class="detail-footer"><text class="caption">记录保留实际操作者及版本；打开原业务时按当前权限重新检查。</text><button class="quiet" @click="openSource(selected)">打开有权访问的原业务 <AppIcon name="right" :size="15"/></button></view></view>
</WorkspaceShell></template>
<style scoped>.audit-filters{padding:23px;margin-bottom:25px}.filter-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.filter-grid .input{font-size:13px}.filter-grid .label{font-size:13px}.filter-actions{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:23px}.filter-actions>.caption{margin-right:auto}.filter-actions>button{font-size:13px;min-width:100px}.audit-list{margin-top:23px}.audit-item{display:flex;align-items:flex-start;gap:16px;border:0;border-bottom:1px solid #e3e8ef;border-radius:0;background:transparent;width:100%;padding:22px 0;text-align:left}.audit-item.selected{background:#edf5ff}.event-icon{width:39px;height:39px;border-radius:50%;background:#edf5ff;display:flex;align-items:center;justify-content:center;flex-shrink:0}.event-body{flex:1;min-width:0}.event-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;font-size:15px;font-weight:600;margin-bottom:8px}.event-time{font-size:12px;font-weight:400;color:#758296}.event-person{font-size:13px;display:block;margin-bottom:5px}.audit-detail{margin-top:24px}.detail-bar{display:flex;align-items:center;justify-content:space-between;padding:18px 23px;border-bottom:1px solid #e3e8ef}.version-comparison{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:25px 23px;background:#edf5ff;font-size:14px}.version-comparison>view{flex:1;min-width:0;overflow-wrap:anywhere}.version-comparison .caption{margin-bottom:7px}.audit-meta{display:grid;grid-template-columns:1fr 1fr;gap:23px;padding:24px}.audit-meta>view>text:last-child{display:block;font-size:12px;margin-top:7px;overflow-wrap:anywhere;line-height:1.8}.detail-footer{padding:20px 23px;border-top:1px solid #e3e8ef;display:flex;align-items:center;justify-content:space-between;gap:18px}.detail-footer>button{display:flex;align-items:center;gap:5px;font-size:12px}.load-more{background:transparent;border:0;color:#3278cf;margin:20px auto;font-size:13px}@media(max-width:680px){.audit-filters{padding:18px 16px}.filter-grid{grid-template-columns:1fr 1fr;gap:17px 12px}.filter-grid .label{font-size:12px}.filter-grid .input{font-size:12px}.filter-actions{flex-wrap:wrap;gap:10px}.filter-actions>.caption{width:100%;font-size:10px}.filter-actions>button{flex:1;min-width:0;font-size:12px}.audit-item{gap:12px;padding:19px 0;flex-wrap:wrap}.event-icon{width:32px;height:32px}.event-heading{font-size:14px;flex-direction:column;align-items:flex-start;gap:5px}.event-time{font-size:10px}.event-person{font-size:12px;line-height:1.7}.audit-item>.status-label{margin-left:44px;font-size:10px}.version-comparison{padding:20px 17px;gap:12px;font-size:12px}.detail-bar{padding:16px}.detail-bar .section-title{font-size:16px}.audit-meta{grid-template-columns:1fr;padding:20px 17px;gap:19px}.detail-footer{flex-wrap:wrap;padding:18px 17px}.detail-footer>.caption{font-size:10px}}
</style>
